class Solution {
    public boolean canReach(int[] arr,int start){
        Queue<Integer> queue=new ArrayDeque<>();
        boolean[] seen=new boolean[arr.length];
        queue.offer(start);
        seen[start]=true;
        while(!queue.isEmpty()){
            int index=queue.poll();
            if(arr[index]==0)return true;
            int[] next={
                index-arr[index],index+arr[index]
            };
            for(int value:next)if(value>=0&&value<arr.length&&!seen[value]){
                seen[value]=true;
                queue.offer(value);
            }
        }
        return false;
    }
}

code.kotlin:
class Solution {
    fun canReach(arr:IntArray,start:Int):Boolean{
        val queue=java.util.ArrayDeque<Int>();
        val seen=BooleanArray(arr.size);
        queue.addLast(start);
        seen[start]=true;
        while(queue.isNotEmpty()){
            val index=queue.removeFirst();
            if(arr[index]==0)return true;
            for(next in intArrayOf(index-arr[index],index+arr[index]))if(next in arr.indices&&!seen[next]){
                seen[next]=true;
                queue.addLast(next)
            }
        };
        return false
    }
}

