class Solution {
    public: bool canReach(vector<int>& arr,int start){
        queue<int> pending;
        vector<bool> seen(arr.size());
        pending.push(start);
        seen[start]=true;
        while(!pending.empty()){
            int index=pending.front();
            pending.pop();
            if(!arr[index])return true;
            for(int next:{
                index-arr[index],index+arr[index]
            })if(next>=0&&next<(int)arr.size()&&!seen[next]){
                seen[next]=true;
                pending.push(next);
            }
        }
        return false;
    }
};
